package br.com.admeclesial.application.sacramento;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import org.springframework.beans.factory.annotation.Autowired;
import br.com.admeclesial.domain.sacramento.*; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import br.com.admeclesial.infrastructure.persistence.sacramento.SacramentoRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.util.StringUtils; import java.time.LocalDate; import java.util.*;
@Service public class SacramentoApplicationService {
 @Autowired private SegurancaOrganizacaoService seguranca;
 private final SacramentoRepository repository; private final OrganizacaoEclesialRepository organizacaoRepository;
 public SacramentoApplicationService(SacramentoRepository r,OrganizacaoEclesialRepository o){repository=r;organizacaoRepository=o;}
 @Transactional public SacramentoResponse criar(SacramentoRequest r){validarAcesso(r.organizacaoEclesialUuid());var org=organizacaoRepository.findByUuid(r.organizacaoEclesialUuid()).orElseThrow(()->new SacramentoBusinessException("Organização eclesial não encontrada.")); if(!org.isAtivo()) throw new SacramentoBusinessException("A organização eclesial está inativa."); if(r.tipo()==TipoSacramento.MATRIMONIO) throw new SacramentoBusinessException("Sacramento de matrimônio deve ser criado pelo fluxo matrimonial."); validarData(r.dataCelebracao()); var e=new Sacramento(); aplicar(e,r,org); return toResponse(repository.save(e));}
 @Transactional public SacramentoResponse atualizar(UUID uuid,SacramentoRequest r){var e=repository.findByUuid(uuid).orElseThrow(()->new SacramentoNotFoundException(uuid)); validarAcesso(e.getOrganizacaoEclesial().getUuid()); validarAcesso(r.organizacaoEclesialUuid()); var org=organizacaoRepository.findByUuid(r.organizacaoEclesialUuid()).orElseThrow(()->new SacramentoBusinessException("Organização eclesial não encontrada.")); if(!org.isAtivo()) throw new SacramentoBusinessException("A organização eclesial está inativa."); if(r.tipo()==TipoSacramento.MATRIMONIO) throw new SacramentoBusinessException("Sacramento de matrimônio deve ser alterado pelo fluxo matrimonial."); validarData(r.dataCelebracao()); aplicar(e,r,org); return toResponse(repository.save(e));}
 @Transactional(readOnly=true) public SacramentoResponse buscar(UUID uuid){var e=repository.findByUuid(uuid).orElseThrow(()->new SacramentoNotFoundException(uuid));validarAcesso(e.getOrganizacaoEclesial().getUuid());return toResponse(e);}
 @Transactional(readOnly=true) public List<SacramentoResponse> listar(){var a=seguranca==null?null:seguranca.organizacoesAutorizadas();return repository.findAllByOrderByDataCelebracaoDesc().stream().filter(e->a==null||a.contains(e.getOrganizacaoEclesial().getUuid())).map(this::toResponse).toList();}
 @Transactional(readOnly=true) public List<SacramentoResponse> listarPorOrganizacao(UUID uuid){validarAcesso(uuid);var org=organizacaoRepository.findByUuid(uuid).orElseThrow(()->new SacramentoBusinessException("Organização eclesial não encontrada.")); return repository.findAllByOrganizacaoEclesialIdOrderByDataCelebracaoDesc(org.getId()).stream().map(this::toResponse).toList();}
 private void aplicar(Sacramento e,SacramentoRequest r,br.com.admeclesial.domain.organizacao.OrganizacaoEclesial org){e.setOrganizacaoEclesial(org);e.setTipo(r.tipo());e.setDataCelebracao(r.dataCelebracao());e.setLocal(text(r.local()));e.setStatus(r.status()==null?StatusSacramento.REGISTRADO:r.status());e.setObservacao(text(r.observacao()));}
 private void validarData(LocalDate d){if(d==null)throw new SacramentoBusinessException("Data da celebração é obrigatória.");}
 private String text(String v){return StringUtils.hasText(v)?v.trim():null;}
 private SacramentoResponse toResponse(Sacramento e){return new SacramentoResponse(e.getUuid(),e.getOrganizacaoEclesial().getUuid(),e.getOrganizacaoEclesial().getNome(),e.getTipo(),e.getDataCelebracao(),e.getLocal(),e.getStatus(),e.getObservacao(),e.getDataRegistro());}
 private void validarAcesso(UUID u){if(seguranca!=null)seguranca.validarAcesso(u);}
}
